INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7554: Glorious Memories Revived', 'The game begins with a historical exposition of French rule over Indochina from 1858 until the outbreak of the Franco-Vietnamese War in 1946. The story follows Hoàng Đăng Bình, a Viet Minh soldier who gets caught up in the war. He is joined by heavy weapons specialist Nguyễn Thế Vinh, marksman Lưu Trọng Hà, and anti-aircraft specialist Hoàng Đăng An. During the game, you switch perspectives between four main protagonists. The story continues through the first Indochina war till its end in 7-5-1954, which explains the title of the game: 7554.' FROM games WHERE igdb_id = 6288 ON CONFLICT (game_id, language_code) DO NOTHING;
