INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LittleBigPlanet 2: Special Edition', 'Exclusive for North America, a Special Edition of LittleBigPlanet 2 was released on November 15th 2011. This edition includes the standard edition of the game, PlayStation Move support, "Move Pack: Rise of the Cakeling" (5 new levels and 7 mini-levels), "Disney/Pixar Toy Story Level" and "Costume" packs, and "Pets Costumes" (the "Dogs", "Cats", and "Even More Animals Costume" packs). The Special Edition was also included as a pack-in game with the 2011 holiday 160GB PS3 system bundles in North America.' FROM games WHERE igdb_id = 21717 ON CONFLICT (game_id, language_code) DO NOTHING;
