INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Football Manager 2012', 'Football Manager 2012 allows you to take control of any club in over 50 nations across the world, including all of the biggest leagues across Europe. You''re in the hot-seat, which means you decide who plays and who sits on the bench, you''re in total control of tactics, team-talks, substitutions and pitch-side instructions as you follow the match live with the acclaimed 3D match engine allowing YOU to make the difference!' FROM games WHERE igdb_id = 8973 ON CONFLICT (game_id, language_code) DO NOTHING;
