INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Splinter Cell 3D', 'As Sam Fisher, Third Echelon''s most skilled Splinter Cell operative, you are assigned to execute a hazardous series of operations to investigate and eliminate a new source of information attacks originating in North Korea. At your disposal is a lethal array of tactics ranging from Combat Knife techniques to experimental prototype weapons skills and more-radical hand-to-hand techniques such as the Inverted Chokehold. Experience the intensity of acting as a lone operative fighting tomorrow''s threats in the field and of cooperating online with a partner to accomplish crucial missions.' FROM games WHERE igdb_id = 47626 ON CONFLICT (game_id, language_code) DO NOTHING;
