INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wanderlust: Rebirth', 'Rebirth is an online four player co-op arcade-action RPG set in the fantasy world, Valandria. The heroes are summoned to Westhaven Arena to prove their worth as heroes of old legend. However, things are not as transparent as they first appear, when our heroes are unknowingly set upon a trek to save mankind from an ominous end. Band together with your fellow brethren to conquer and change the course of destiny.' FROM games WHERE igdb_id = 15302 ON CONFLICT (game_id, language_code) DO NOTHING;
