INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil: The Mercenaries 3D', 'Resident Evil: The Mercenaries 3D is an action-oriented title where players can choose any of eight playable characters to shoot, explode and melee their way through swarms of enemies. Featuring re-mastered stages from Resident Evil 4 and Resident Evil 5, the game is a race against time as players try to defeat as many enemies as possible before the countdown reaches zero. The experience is available both as solo and multiplayer, where gamers across the world can team up and enjoy two-player co-op.' FROM games WHERE igdb_id = 976 ON CONFLICT (game_id, language_code) DO NOTHING;
