INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medieval Moves: Deadmund''s Quest', 'The evil Sorcerer Morgrimm has invaded Prince Edmund''s Castle and plots to take over the kingdom, raising an army of skeletons from beyond. Now you must fight Morgrimm and his minions to restore order to the kingdom! Use the fluid PS Move motion-controls to battle your foes using swords, arrows, throwing stars and more! Let the adventure begin!' FROM games WHERE igdb_id = 18230 ON CONFLICT (game_id, language_code) DO NOTHING;
