INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario & Sonic at the London 2012 Olympic Games', 'Mario & Sonic at the London 2012 Olympic Games is a collection of numerous events based on the Olympic Games. Mario & Sonic brings together the two titular characters and eighteen more from both franchises to participate in environments based on the official venues of the 2012 Summer Olympics in London. The characters are divided into four categories: all-around, speed, power, and skill.' FROM games WHERE igdb_id = 2708 ON CONFLICT (game_id, language_code) DO NOTHING;
