INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Homefront', 'Featuring a compelling single player story crafted by John Milius (Apocalypse Now, Red Dawn), Homefront immerses gamers in an interactive and cinematic FPS experience where they will assume an infantry role or take command of a wide variety of aerial and ground vehicles. In addition to the single-player experience, Homefront will deliver a robust multiplayer experience. In a land stripped of freedom, the brave will fight for their home.' FROM games WHERE igdb_id = 1885 ON CONFLICT (game_id, language_code) DO NOTHING;
