INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlefield 3', 'In Battlefield 3, players step into the role of the elite U.S. Marines. As the first boots on the ground, players will experience heart-pounding missions across diverse locations including Paris, Tehran and New York. As a U.S. Marine in the field, periods of tension and anticipation are punctuated by moments of complete chaos. As bullets whiz by, as walls crumble, as explosions force players to the ground, the battlefield feels more alive and interactive than ever before.' FROM games WHERE igdb_id = 343 ON CONFLICT (game_id, language_code) DO NOTHING;
