INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forsaken World', 'Unite against the dark forces that threaten the world of Eyrda in Forsaken World. Choose between seven distinct races including the Stonemen, Elves, Dwarves, Humans, the Kindred, Lycan and Demon, each with their own in-depth narrative and history. Roam through an ever-changing land, discover an advanced guild system and immerse yourself in a dark, fantasy world.' FROM games WHERE igdb_id = 11231 ON CONFLICT (game_id, language_code) DO NOTHING;
