INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Global Ops: Commando Libya', 'Global Ops: Commando Libya is a third-person shooter that puts players at the heart of a global race to capture a nuclear warhead that’s been stolen by Russian organized crime, and get it back into safe hands before it becomes a terrorist weapon. Players will take part in a deadly global chase -- battling through Greenland and into North Africa as they fight to take down terrorist forces and recapture the devastating weapon.' FROM games WHERE igdb_id = 10365 ON CONFLICT (game_id, language_code) DO NOTHING;
