INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('transformers-dark-of-the-moon', 5243, '2011-06-14', 44, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3985.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scegrn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transformers: Dark of the Moon', 'The Transformers: Dark of the Moon video game allows players to fight through the epic battles on Earth that will shape the events of the movie. Armed with a brand-new gameplay mechanic, fans will harness the power of Stealth Force to instantly convert to a third, hybrid state that combines the weapons and firepower of robot mode with the agility and maneuverability of vehicle mode. Set in unique environments around the world such as the Jungles of South America, Siberian military facilities, Detroit Cityscapes and more, the game lets players assume the roles of a diverse roster of everyone''s favorite Transformers from the movie through a heart-pounding campaign to save mankind. Additionally, fans can play the game with or against their friends through intense, online multiplayer game modes as their favorite iconic characters.' FROM games WHERE igdb_id = 5243 ON CONFLICT (game_id, language_code) DO NOTHING;
