INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fight Night Champion', 'Fight Night Champion is a boxing video game developed by EA Canada and published by EA Sports. It is the fifth entry in the Fight Night series and was released on March 1, 2011 for the PlayStation 3 and Xbox 360. The game takes a drastic turn from its predecessors, depicting a "grittier", "darker" setting with animations and player damage that "truly conveys the brutality of the sport of boxing."' FROM games WHERE igdb_id = 6356 ON CONFLICT (game_id, language_code) DO NOTHING;
