INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kung-fu-panda-2', 4965, '2011-05-24', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22s7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sceh7e.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kung Fu Panda 2', 'Kung Fu Panda 2: The Video Game begins where the movie leaves off, as Po and the Furious Five venture out to save Kung Fu from a new evil threat. In an original story, players are plunged into the video game at the climatic end-of-movie battle between Master Shen and Po. Players must help Po, and the furious five journey to save Gongman City, restore balance and save Kung Fu. Players will also get assistance from the councel of respected masters, Shifu, Croc, and Ox to help defeat looting wolves, powerful gorillas and clans of barbaric komodo dragons lead by Xaio Dan. There will be effective defensive combo sequences for players to learn as you defeat your enemies alongside the Furious Five. Use strategy and problem solving to master Kung Fu. Players will get to play through an all new story adventure with epic battles and new barbaric enemies. Engage with physical combat and combos or use strategy and problem solving skills to get through your battles.' FROM games WHERE igdb_id = 4965 ON CONFLICT (game_id, language_code) DO NOTHING;
