INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The House of the Dead: Overkill - Extended Cut', 'The House of the Dead: Overkill Extended Cut deposits you in a retro, B movie-style world crawling with monstrous zombies hungry for your brain. Rediscover the nightmare with seven remastered levels and two new exclusive levels, all in stunning 3D with remastered HD graphics. New baby mutants and a radical new crossbow with explosive bolts refresh the gameplay and add a whole new element of terror to the mutant-shooting fun.' FROM games WHERE igdb_id = 44614 ON CONFLICT (game_id, language_code) DO NOTHING;
