INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('black-rock-shooter-the-game', 11831, '2011-08-25', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2f5w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpztr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Rock Shooter: The Game', 'Black Rock Shooter: The Game is an action role-playing game and based on the Black Rock Shooter franchise created by Huke. The players take on the role of the eponymous Black Rock Shooter. The game is divided into several missions in which the player must clear objectives to progress. On the main overworld, BRS can explore the available areas and look for certain items. Battles begin when the player comes into contact with an enemy on the overworld. During a battle, BRS can aim and shoot with her rock cannon at enemies, block against attacks, and sidestep to avoid them completely. If the player fires the rock cannon or uses the sidestep too much in a short time, the system will overheat, leaving the player vulnerable to attack until it cools down. Throughout the game, players can earn abilities that can be equipped to BRS and used in battle, each with their own cooldown periods. These include offensive attacks such as a powerful blast, a sniper rifle, or support abilities that can increase BRS'' stats such as her attack or defense. Certain sections will also see BRS ride a motorcycle, in which she can attack enemies on either side of her or use weapons to fire in front of enemies.' FROM games WHERE igdb_id = 11831 ON CONFLICT (game_id, language_code) DO NOTHING;
