INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Souls: Enchanted Paintings', 'After the police and FBI come up empty in their investigation, Bella turns to forces beyond our world to find her missing son in Lost Souls: Enchanted Paintings! A mysterious package with no return address appears on Bella’s doorstep and now her entire world is about to be turned upside down! Use your Hidden Object Puzzle Adventure talents to explore this incredible game and save Bella’s son!' FROM games WHERE igdb_id = 88750 ON CONFLICT (game_id, language_code) DO NOTHING;
