INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('apox', 9981, '2011-01-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6a4g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sinj5p17dgqwsftjlwbx.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apox', 'Apox is a real-time strategy game that uniquely includes gameplay concepts from first-person shooters. Like in a FPS, you can prone, crouch, switch active weapons, throw grenades, and loot corpses. Soldiers in Apox have limited ammo, but ammo sharing is done seamlessly. Soldiers can be placed in vehicles, and this essentially lets you create your own unit designs. Apox keeps everything that makes RTS great like making bases, controlling strategic sites, and managing your resources.' FROM games WHERE igdb_id = 9981 ON CONFLICT (game_id, language_code) DO NOTHING;
