INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crysis 2', 'Sequel to one of the greatest PC shooters ever, Crysis 2 offers console players their first taste of Crytek''s unique shooter gameplay. Featuring futuristic war, gorgeous destruction and the chance to kick alien butt on the grandest stage of all, New York City, Crysis 2 is destined at the least to equal its predecessor, if not surpass it. Additional features include: challenging AI enemies in the single player campaign, 12-player support online, new and improved upgradable Nanosuit 2 technology and more.' FROM games WHERE igdb_id = 471 ON CONFLICT (game_id, language_code) DO NOTHING;
