INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('doctor-lautrec-and-the-forgotten-knights', 6757, '2011-07-07', 46, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5tv6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/i90gwrdh2mocfcwjptru.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doctor Lautrec and the Forgotten Knights', 'Enter 19th century Europe and the world of Doctor Jean-Pierre Lautrec. He''s a brilliant, eccentric, sarcastic professor with few friends but a healthy obsession for solving mysteries. One day, a woman named Marie visits Lautrec bearing a curious gadget. The mysterious map that the gadget displayed seemed to point the way to a fantastic hidden treasure belonging to Louis XIV of the House of Bourbon, a dynasty that had collapsed a century earlier. As they search for the treasure, they find themselves targeted by a mysterious man named Vidocq. They are blocked at every turn by the Knights of the Iron Mask, a mysterious group of men with iron masks and claws. Work as Doctor Lautrec, aided by his perky and emotional sidekick Sophie, to unlock the mysteries within and search for the lost treasure of Louis XIV. Search for clues, solve puzzles to unlock new mysteries and gain more information as the quest continues. The story is told in both 2D and uses the power of the Nintendo 3DS in 3D to enhance game play giving gamers the ability to look around for clues like they''re in the game. Immerse yourself in the world of Doctor Lautrec where mystery and adventure can be found around every corner.' FROM games WHERE igdb_id = 6757 ON CONFLICT (game_id, language_code) DO NOTHING;
