INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ugly-americans-apocalypsegeddon', 20618, '2011-07-03', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/etevhyrexvq5zl0bepjc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lapzquoewxvzkfbozrrz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ugly Americans: Apocalypsegeddon', 'With four-player top-down co-op gameplay that hearkens back to such classics as Gauntlet and Robotron, "Ugly Americans: Apocalypsegeddon" features four playable characters, each with their own unique abilities, weapons and strengths. Players must comb the streets of New York City and pacify raving demons, delinquent man birds and zombies by lactating fire or hurling wacky objects like flying demon skulls, fish, baseballs and wrenches.' FROM games WHERE igdb_id = 20618 ON CONFLICT (game_id, language_code) DO NOTHING;
