INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eryi''s Action', 'Eryi''s Action is a 2D ‘trapformer’ by developer Xtal Sword that is visually inspired by Super Mario, but has gameplay akin to games like I Wanna Be the Guy. Don’t be fooled by its adorably charming looks – this game abounds in traps and wants you to die! However, where IWBTG was murderously difficult, Eryi''s Action is additively challenging and FUN! Trap placement is often laugh-out-loud funny and seriously engaging. Some traps simply need to be learned to avoided, but others are puzzles that will require your skill and wits to beat.' FROM games WHERE igdb_id = 10278 ON CONFLICT (game_id, language_code) DO NOTHING;
