INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyperdimension Neptunia Mk2', 'Hyperdimension Neptunia mk2 is the second game in the Hyperdimension Neptunia franchise and the sequel to the first game. The game features the Goddesses'' little sisters as the main characters, with Neptune''s little sister Nepgear as the protagonist. The game features significantly changed battle mechanics compared to the first game and features 3D models instead of 2D sprites.' FROM games WHERE igdb_id = 7320 ON CONFLICT (game_id, language_code) DO NOTHING;
