INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaga Legions DX', 'The legendary hit arcade shooter returns with Galaga Legions DX! Featuring a new twist on the classic gameplay, slick new graphics and devastating weapon power-ups, the fate of the galaxy lies in your hands! Board your fighter and prepare to defend Earth from wave after wave of relentless aliens. Target your enemies'' critical weak spots to earn bonuses and rack-up an astronomical score! Blast your way through unique levels and epic boss battles on your mission to defend the galaxy and prevent an intergalactic catastrophe!' FROM games WHERE igdb_id = 10762 ON CONFLICT (game_id, language_code) DO NOTHING;
