INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cargo! The Quest for Gravity', 'Cargo! The Quest for Gravity is an action-adventure simulation game packed with unique and innovative physics-driven gameplay that offers multiple solutions to each mission; not to mention an unlimited sandbox mode! Create crazy, yet functional, custom vehicles to solve missions with your own unique style! Explore a wide variety landscapes and locations including flying islands, large underwater environments, and numerous interiors. Changing seasons offer a dynamic effect on gameplay.' FROM games WHERE igdb_id = 9792 ON CONFLICT (game_id, language_code) DO NOTHING;
