INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris: Axis', 'The original portable Tetris game was a smash hit on the Game Boy system. The new Tetris: Axis game lets players use the magic of the Nintendo 3DS system to jump into the action in 3D without the need for special glasses. The game includes more than 20 different modes – some familiar, some new. Up to eight players can compete in wireless multiplayer battles, even if only one player has a game card.' FROM games WHERE igdb_id = 6896 ON CONFLICT (game_id, language_code) DO NOTHING;
