INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sideway New York', 'Battle your way through a twisted graffiti world where your prowess in puzzle solving makes the difference between life and death! Jump into one of the most unique and visually compelling 3D game worlds ever created. Follow the twisted journey of Nox, through a fast-paced 2D adventure set in a 3D world. Unlock new abilities to defeat enemies and rescue friends. Beware, in Sideway New York, you’re in a world where your favorite color might just kill you.' FROM games WHERE igdb_id = 16273 ON CONFLICT (game_id, language_code) DO NOTHING;
