INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cabela-s-big-game-hunter-2012', 6649, '2011-09-27', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co60b7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tni19kdws4rns12azbss.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Big Game Hunter 2012', 'With the world as their playground, players will explore a vast expanse of mountains and valleys with unprecedented choices in direction never before seen in a Cabela''s hunting game. Players can climb an area to get a better angle for the shot but risk being spotted, or they can take a low elevation route with poor visibility but plenty of concealment. Nature doesn''t always wait for you to make the first move as the dynamic weather and natural hazards make the hunt even more challenging. The challenge doesn''t end there. Cabela''s Big Game Hunter 2012 ups the ante with the most realistic animals ever seen in the Cabela''s series. Every animal''s unique movement gives clues on what the animal will do next. In order to bag the trophies, players will have to avoid detection through cunning, skill, and deception. They must also utilize master hunting skills such as advanced stalking techniques so they can quickly move through cover and close in on their targets.' FROM games WHERE igdb_id = 6649 ON CONFLICT (game_id, language_code) DO NOTHING;
