INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewel Quest: Expeditions', 'Jewel Quest: Expeditions is a "match 3" puzzle played on a grid filled with various colored gem tiles. The player may swap any two adjacent tiles, as long as the swap results in a horizontal or vertical line of three or more matching tokens. The matched set disappears, allowing gem tiles to drop into the gaps from above; if more matched sets form as a result, they disappear as well.
