INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Siege III', 'Dungeon Siege III (DSIII or DS3) is an action role-playing game developed by Obsidian Entertainment and published by Square Enix for the PlayStation 3, Xbox 360 and Microsoft Windows.[5] Chris Taylor, the original creator of Dungeon Siege, served as an advisor during the development of the game. It is the third game in the series not to be developed by Gas Powered Games, (after Dungeon Siege: Legends of Aranna by Mad Doc Software and Dungeon Siege: Throne of Agony by SuperVillain Studios) and the first to be published by Square Enix after it acquired the complete ownership of the Dungeon Siege franchise. It was released on June 17, 2011. (wiki, 2014)' FROM games WHERE igdb_id = 5988 ON CONFLICT (game_id, language_code) DO NOTHING;
