INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Major Mayhem', 'Arcade cover shooter inspired by Time Crisis, Metal Slug and 80''s action heros! He''s got an itchy trigger finger, some scratchy stubble, and a fondness for shooting dudes in the face. Run and gun your way through gorgeous 3D environments as you embark on a mission to rescue your kidnapped girlfriend from the Forces of Evil. Guns, grenades and an assortment of other tools of destruction are at your disposal, and you''ll need every last one of ''em. So what are you waiting for, Major Mayhem? The future of the Free World -- and your love life -- hangs in the balance.' FROM games WHERE igdb_id = 16855 ON CONFLICT (game_id, language_code) DO NOTHING;
