INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Portal 2', 'Sequel to the acclaimed Portal (2007), Portal 2 pits the protagonist of the original game, Chell, and her new robot friend, Wheatley, against more puzzles conceived by GLaDOS, an A.I. with the sole purpose of testing the Portal Gun''s mechanics and taking revenge on Chell for the events of Portal. As a result of several interactions and revelations, Chell once again pushes to escape Aperture Science Labs.' FROM games WHERE igdb_id = 72 ON CONFLICT (game_id, language_code) DO NOTHING;
