INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Oregon Trail: 40th Anniversary Edition', 'Relive a part of American history and a slice of gaming history at the same time as a classic frontier adventure blazes a new trail on Wii. In the middle of the 19th Century, America is headed West, chasing the promise of a new life. Load up the wagon and set out from Independence, Missouri, making your way to Oregon City on a trail full of adventure. Face the challenges of the wide-open frontier as you battle the elements, hunt and fish to feed your family, and more.' FROM games WHERE igdb_id = 202693 ON CONFLICT (game_id, language_code) DO NOTHING;
