INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 2011', 'F1 2011 puts players in the driver''s seat of the 2011 FIA Formula One World Championship, featuring all official teams, drivers, and circuits including the new Buddh International Circuit in India and the Nürburgring. Players can progress through a career mode to become World Champion, challenge others in split-screen and online multiplayer with up to 24 cars on track, or set records in Time Attack mode. The game incorporates 2011 season mechanics like KERS and DRS systems, while expanding the off-track experience with detailed paddock areas, media interactions, and post-race celebrations.' FROM games WHERE igdb_id = 1374 ON CONFLICT (game_id, language_code) DO NOTHING;
