INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Ghost Recon: Shadow Wars', 'Build, train, and equip the ultimate elite special ops team using the latest in high-tech weapons and gear. From the hot deserts of Kazakhstan to the towns and villages of Ukraine and the frozen lands of Siberia, you must discover and disable the secret Soviet-era "Dead Hand" bases which Russian ultranationalist Yuri Treskayev is using to build an army of drones to seize power.' FROM games WHERE igdb_id = 1303 ON CONFLICT (game_id, language_code) DO NOTHING;
