INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted: Golden Abyss', 'Uncover the dark secret behind the 400-year-old massacre of a Spanish expedition as Nathan Drake tracks the murderous trail of an ancient and secret Spanish sect. Caught in the middle of a rivalry between Jason Dante - his old friend - and Marisa Chase - the granddaughter of an archeologist who has mysteriously vanished without a trace - Nathan Drake delves into the treacherous river basins, undiscovered temple ruins and karst caverns of Central America in search of a legendary lost city, only to find himself pushed to the edge of the Golden Abyss' FROM games WHERE igdb_id = 998 ON CONFLICT (game_id, language_code) DO NOTHING;
