INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halo: Combat Evolved Anniversary', 'Halo: Combat Evolved Anniversary is a spectacular remastered version of the original game, created to celebrate the 10th anniversary of one of the most beloved first-person shooters in gaming history. Bundled with seven of the most popular multiplayer maps in Halo history ready for Xbox Live, Halo: Anniversary includes a bounty of new features including cooperative play over Xbox Live, Achievements, new challenges, and new fiction to uncover.' FROM games WHERE igdb_id = 2640 ON CONFLICT (game_id, language_code) DO NOTHING;
