INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DC Universe Online', 'DC Universe Online is a free-to-play superhero / supervillian MMORPG that lets players create their own unique tights-wearing hero or villain and roam the streets of places like Gotham City and Metropolis fighting or creating crime. Players fight alongside such iconic DC Comics characters as Superman and Batman, Lex Luthor and The Joker, and many others. Excellent physics help bring comic book action and combat to life, all under the creative direction of noted comic book artist Jim Lee.' FROM games WHERE igdb_id = 576 ON CONFLICT (game_id, language_code) DO NOTHING;
