INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Witcher 2: Assassins of Kings', 'This third-person dark fantasy Western RPG and sequel to The Witcher (2007), featuring multiple endings and branching narrative paths, follows the travels of Geralt of Rivia, witcher, who, after being falsely accused of regicide, sets out to clear his name and find the real killer, in a time of political turmoil and the brink of war between the imperialistic Nilfgaardian Empire and the Four Kingdoms.' FROM games WHERE igdb_id = 478 ON CONFLICT (game_id, language_code) DO NOTHING;
