INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('need-for-speed-the-run', 526, '2011-11-15', 67, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20a4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/s1adv3wammrmzubrp3o4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: The Run', 'Need for Speed The Run lures players into an underground world of illicit, high-stakes racing. The heat is on - and it isn''t just the fuzz who are after you. Entering the race is just the beginning as you blow across borders, weave through dense urban traffic, rocket down icy mountain passes and navigate narrow canyons at breakneck speeds. Powered by DICE''s state-of-the-art Frostbite 2 engine, Need for Speed The Run takes the action racing genre to new heights with stunning visuals and car physics that hug the road even at top speeds all built around a gripping storyline. The cars are hot, the racing is intense and the story will have you at the edge of your seat… all the way from the Golden Gate Bridge to the Empire State building.' FROM games WHERE igdb_id = 526 ON CONFLICT (game_id, language_code) DO NOTHING;
