INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('otomedius-excellent', 1695, '2011-04-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8iym.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sceh51.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Otomedius Excellent', 'The lovely rocket-riding ladies of Otomedius Gorgeous arrive in the US for the first time in Otomedius Excellent, the highly anticipated sequel to the Japan-exclusive arcade hit. Otomedius Excellent is an Xbox 360 exclusive and features nearly ten playable characters, heart-pounding classic Gradius-style shoot-em-up gameplay, a dazzling array of stunning visuals, thrilling multiplayer action locally or via a connection to Xbox LIVE, an improved upgrade system, downloadable content and of course the Otomedius Excellent game disc. With all this and more it is sure to be the must-own arcade style shooter for Xbox 360 players in 2011 and beyond.' FROM games WHERE igdb_id = 1695 ON CONFLICT (game_id, language_code) DO NOTHING;
