INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ncis', 21726, '2011-10-28', 57, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2d0i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ta6ydbw4y0zb8knlc30j.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCIS', 'For the first time ever, the world of the NCIS TV show comes to your living room in an all-new NCIS story arc written with the writers of the show. Work as the NCIS team to solve complex murder, espionage and terrorist cases. Discover exciting connections between the four original cases as you crack each one, and work towards solving the overall investigation. Bond with your favorite NCIS characters and get first-hand experience with the group’s humor, personality quirks, and defining characteristics. Interact with the characters through layers of storyline and dialogue designed to make you an integral part of the cast’s compelling dynamic. Through a variety of mini-games: search crime scenes for clues and collect evidence; use the latest forensic tools and perform autopsies; conduct dramatic suspect interrogations; put your reflexes to the tests in tense action sequences. Finally piece the clues together using your wits to deduct the truth.' FROM games WHERE igdb_id = 21726 ON CONFLICT (game_id, language_code) DO NOTHING;
