INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatoful Boyfriend', 'Congratulations! You''ve been accepted as the only human student at the prestigious St. PigeoNation''s Institute, a school for talented birds! Roam the halls and find love in between classes as a sophomore student at the world''s greatest pigeon high school. Finding happiness won''t be easy, but it’s not all academic — there''s always time for a little romance in this delightful remake of Hato Moa''s popular visual novel / avian dating sim Hatoful Boyfriend!' FROM games WHERE igdb_id = 8874 ON CONFLICT (game_id, language_code) DO NOTHING;
