INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Battles: Ninjago', 'Build your army, battle your enemies and become a master of Spinjitzu as you recover powerful ninja weapons and restore the world''s harmony in LEGO Battles: Ninjago! Deploy Hero troops through exciting missions and adventures to defeat the sinister Skulkin forces, play as the bad guys and face-off against ninjas of Spinjitzu, or challenge a friend in thrilling multiplayer battles to see whose army ranks supreme.' FROM games WHERE igdb_id = 19767 ON CONFLICT (game_id, language_code) DO NOTHING;
