INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons', 'Dungeons follows the misadventures of the foremost of all Dungeon Lords, who spends his time luring heroes into his labyrinthine creations with the promise of treasure and a good fight--only to be trapped by his ingenious devices. Once they are in his grasp, our Dungeon Lord must look after and cherish his new prisoners until they are more comfortable with their surroundings because come the "harvest," happy heroes have more precious soul energy for you to gleefully extract via twisted torture chambers.' FROM games WHERE igdb_id = 8849 ON CONFLICT (game_id, language_code) DO NOTHING;
