INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario 3D Land', 'Super Mario 3D Land is the second 3D Super Mario platformer for a handheld device, and the successor to Super Mario Galaxy 2. The game is closely based on side-scrolling Mario games, as it combine elements from both traditional 2D Mario games and modern free-roaming 3D Mario games. It also introduces elements into the series, including power-ups and gameplay mechanics.' FROM games WHERE igdb_id = 1079 ON CONFLICT (game_id, language_code) DO NOTHING;
