INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Kart 7', 'The seventh installment of the fan-favorite Mario Kart franchise brings Mushroom Kingdom racing fun into glorious 3D. For the first time, drivers explore new competitive kart possibilities, such as soaring through the skies or plunging to the depths of the sea. New courses, strategic new abilities and customizable karts bring the racing excitement to new heights.' FROM games WHERE igdb_id = 2349 ON CONFLICT (game_id, language_code) DO NOTHING;
