INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Orchestra 2: Heroes of Stalingrad', 'Red Orchestra 2: Heroes of Stalingrad, the leading tactical multiplayer WWII shooter on the PC, will take the award winning Red Orchestra franchise into the next generation of gaming. Cutting edge graphics and audio built using the Unreal Engine 3, inventive features and streamlined realism will deliver an unrivalled tactical shooter experience.' FROM games WHERE igdb_id = 1055 ON CONFLICT (game_id, language_code) DO NOTHING;
