INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors 7: Xtreme Legends', 'The Dynasty Warriors series let you step into the shoes of the greatest generals in Ancient China. In this Tactical Action game players can enjoy the thrill of taking down thousands of enemies and become the greatest hero in Chinese history. Dynasty Warriors 7: Xtreme Legends is a stand-alone expansion that supercharges the world of Dynasty Warriors 7 with many different enhancements.' FROM games WHERE igdb_id = 6833 ON CONFLICT (game_id, language_code) DO NOTHING;
