INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsune Miku: Project Diva Extend', 'Hatsune Miku: Project Diva Extend is a rhythm game and an enhanced version of the 2010 title, Hatsune Miku: Project Diva 2nd. Like the original the game primarily makes use of Vocaloids, a series of singing synthesizer software, and the songs created using these vocaloids most notably the virtual-diva Vocaloid Hatsune Miku. The gameplay remains the same as in the previous game, but Extend features a larger set of songs and modules. Similar to past games in the series, a companion game Hatsune Miku: Project Diva Dreamy Theater Extend was released on the PlayStation 3 with improved visuals and it also supports stereoscopic 3D for the first time in the series.' FROM games WHERE igdb_id = 11767 ON CONFLICT (game_id, language_code) DO NOTHING;
