INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scribblenauts Remix', 'Scribblenauts Remix is an emergent action puzzle game developed by 5th Cell and Iron Galaxy Studios and published by Warner Bros. Interactive on October 12, 2011. The game provides forty levels from both Scribblenauts and its sequel, Super Scribblenauts along with ten new levels for iOS and Android. The mechanics of the game are based on Super Scribblenauts, allowing for the use of adjectives in addition to nouns. The game uses built-in features of iOS, such as the touch keyboard, and was released simultaneously with iOS version 5, incorporating new features such as cloud storage via iCloud to play the game across multiple devices. The game also features Game Center integration.' FROM games WHERE igdb_id = 8806 ON CONFLICT (game_id, language_code) DO NOTHING;
