INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worms Crazy Golf', 'Worms Crazy Golf is a hilarious mixture of the explosive action of Worms and the puzzle-based challenges of crazy golf! All of the trademark Worms humour, comic violence, and cartoon visuals are present, combined with addictive yet accessible golf gameplay. With extensive and re-playable single-player options, and hot-seat multi-player for up to 4 players, this is not just a load of balls.' FROM games WHERE igdb_id = 15070 ON CONFLICT (game_id, language_code) DO NOTHING;
