INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raving Rabbids: Alive and Kicking', 'Raving Rabbids: Alive & Kicking, known as Rabbids: Fuori di schermo in Italy, is a video game which was released by publisher and developer Ubisoft (Ubisoft Paris and Ubisoft Milan) on November 3, 2011 in Australia, November 4, 2011 in Europe and November 8, 2011 in North America for the Xbox 360 video game platform. This is the sixth game from the Raving Rabbids games franchise and it is the only Rabbids game not released on a Nintendo platform. The game was exclusively developed for the Kinect and consists of mini-games with up to 4 players. It was presented at the 15th E3 in Los Angeles, California, United States.' FROM games WHERE igdb_id = 20221 ON CONFLICT (game_id, language_code) DO NOTHING;
