INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Case Files: Escape from Ravenhearst', 'Mystery Case Files: Escape from Ravenhearst is an adventure-puzzle casual game developed by Big Fish Studios and distributed by Big Fish Games. It is the eight installment in the Mystery Case Files series and third and final installment in the Ravenhearst story-arc. The Collector''s Edition is available exclusively on the Big Fish Games website.' FROM games WHERE igdb_id = 5516 ON CONFLICT (game_id, language_code) DO NOTHING;
