INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gods & Heroes: Rome Rising', 'Gods & Heroes: Rome Rising is a mature, full-scale, action-adventure, massively multiplayer online role-playing game that immerses the audience in Roman mythology. Players strap on gladiator armor, lay waste to monsters and command minions while seeking favor from the gods. Each player''s character is a Demigod, a child of both a god and a mortal, and is a celebrated Hero. These brave warriors combat an ancient enemy, the Telchine gods, who have returned to topple the empire and avenge their defeat at the hands of the Olympian gods.' FROM games WHERE igdb_id = 10368 ON CONFLICT (game_id, language_code) DO NOTHING;
