INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Way of the Samurai 4', 'In Way of the Samurai 4, you must take on the role of a master-less samurai looking to establish yourself in this conflicted land of opportunity and uncertainty. Set in he humble port town of Amihama during the mid 19th Century, several years after the arrival of the "black ships" from the West ended Japan''s long history of cultural isolation. It is up to you to decide which faction to support in an almighty conflict amongst the region''s three powers, and so direct the course of Japan''s history.' FROM games WHERE igdb_id = 10158 ON CONFLICT (game_id, language_code) DO NOTHING;
