INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nancy Drew: Alibi in Ashes', 'A local contest turns into an arson scene and now deceit smolders among the charred ruins of the River Heights Town Hall. Police have several suspects, but well-placed incriminating evidence and poisonous local gossip compelled authorities to make only one arrest: Nancy Drew. Can you, as the teenage detective and her closest friends, catch the real arsonist and extinguish the accusations among the embers?' FROM games WHERE igdb_id = 10579 ON CONFLICT (game_id, language_code) DO NOTHING;
