INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The First Templar', 'The First Templar follows the story of two main characters – a French Templar, and his companion, a noble lady who has been proclaimed a heretic. Taking control over these two unlikely allies, the player must uncover the mysteries behind the Templar Order, play a role in a grand conspiracy, and discover the secret of the Holy Grail. The heroes face powerful opponents at every turn, including Sacracen, King Philip the IV of France and the Inquisition.' FROM games WHERE igdb_id = 6994 ON CONFLICT (game_id, language_code) DO NOTHING;
