INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Trading Card Game Online', 'Have fun learning and mastering the Pokémon Trading Card Game Online! Practice against the computer or go head to head with your friends or other players from around the world. Unlock cards and decks as you play to build up your collection and make truly unique decks. Your decks and card collection are stored as a part of your Pokémon Trainer Club account, allowing you to switch between tablet and desktop with ease.' FROM games WHERE igdb_id = 24423 ON CONFLICT (game_id, language_code) DO NOTHING;
