INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Payday: The Heist', 'Payday: The Heist is an action filled first person shooter that lets players take on the role of a hardened career criminal executing intense, dynamic heists in constant pursuit of the next “big score”. Load out with an array of weaponry and equipment. Navigate six high-stake heists with three other live or A.I. Co-Op partners in crime.' FROM games WHERE igdb_id = 1381 ON CONFLICT (game_id, language_code) DO NOTHING;
