INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Seiya: Sanctuary Battle', 'Saint Seiya: Sanctuary Battle immerses players in the most popular drama from Saint Seiya: the Sanctuary, as Seiya and his companions fight side by side to defeat the gold saints of the twelve palaces and protect Athena. As players complete quests and progress through the twelve levels, they can inflict tremendous damage on their foes with fast-paced Cosmo power-up attacks.' FROM games WHERE igdb_id = 25184 ON CONFLICT (game_id, language_code) DO NOTHING;
