INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Post Apocalyptic Mayhem', 'Post Apocalyptic Mayhem lets you race and battle heavily-modified vehicles through numerous breathtaking tracks and lay waste to other racers in over-the-top vehicular mayhem. You can use special vehicle abilities to cause spectacular destruction to enemy cars as you fight and speed to victory. You’ll experience remarkable speeds, hilarious and violent weapons, reinforced vehicles and various exhilarating tracks.' FROM games WHERE igdb_id = 16229 ON CONFLICT (game_id, language_code) DO NOTHING;
