INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cartoon-network-punch-time-explosion-xl', 21151, '2011-11-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2et9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8h5r.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Network: Punch Time Explosion XL', 'Did you ever wonder what would happen if Humungousaur and Samurai Jack met up in a dark alley? What if Dexter took on Mac and Bloo? The possibilities are endless! If only there was a way to get all your favorite cartoon characters together... Well you don''t have to wait any longer... Get ready for a Punch Time Explosion! Cartoon Network Punch Time Explosion XL is a fighting game featuring characters from some of the most iconic shows on Cartoon Network. This is the network''s first ever all-star brawler! Fans can go to toe-to-toe with characters from 11 of Cartoon Network''s shows including The Powerpuff Girls, Dexter''s Laboratory, Chowder and many more.' FROM games WHERE igdb_id = 21151 ON CONFLICT (game_id, language_code) DO NOTHING;
