INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yar''s Revenge', 'A reimagining (titled Yar''s Revenge, rather than Yars'' Revenge) was released as a downloadable title on April 12, 2011 on Xbox Live Arcade and on April 28, 2011 for Microsoft Windows. It was developed by Killspace Entertainment and published by Atari. In this version, the eponymous Yar has been reimagined as a humanoid female in mechanized power armor.' FROM games WHERE igdb_id = 28721 ON CONFLICT (game_id, language_code) DO NOTHING;
