INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brink', 'Brink is an immersive first-person shooter that blends single-player, co-op, and multiplayer gameplay into one seamless experience, allowing you to develop your character whether playing alone, with your friends, or against others online. You decide the combat role you want to assume in the world of Brink as you fight to save yourself and mankind''s last refuge. Brink offers a compelling mix of dynamic battlefields, extensive customization options, and an innovative control system that will keep you coming back for more.' FROM games WHERE igdb_id = 502 ON CONFLICT (game_id, language_code) DO NOTHING;
