INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resistance 3', 'The third and currently final installment in the Resistance series. Resistance 3 portrays Capelli''s heroic survival inside the brutal Resistance world. Featuring new upgradeable weapons, the return of the weapon wheel, two-player online or split-screen campaign co-op and a progression-based multiplayer experience, Resistance 3 delivers a heroic-yet savage first-person shooter experience.' FROM games WHERE igdb_id = 3206 ON CONFLICT (game_id, language_code) DO NOTHING;
