INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brink of Consciousness: Dorian Gray Syndrome', 'Venture into the realm of a madman to free your beloved from captivity in this hidden object adventure! As reporter Sam Wilde, you must work quickly to unravel a bizarre series of disappearances involving young and beautiful people. Sam''s every move is being tracked so he has to be extra careful. Putting his journalistic talents to the test, Sam must find the maniac who has kidnapped Anna, and stop him before it''s too late.' FROM games WHERE igdb_id = 50313 ON CONFLICT (game_id, language_code) DO NOTHING;
