INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gatling Gears', 'When the Empire begins its reign of destruction in a thirst for natural resources, it’s up to Max Brawley, a retired Gatling Gear pilot, to stop them. Together with his niece and his trusty Gatling Gear unit he must fight his way to the heart of the Empire and eliminate the destruction at its source.' FROM games WHERE igdb_id = 15134 ON CONFLICT (game_id, language_code) DO NOTHING;
