INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luxor HD', 'Experience LUXOR in stunning HD! Answer the call of the goddess, Isis, in this addictive marble-shooter game. Chains of colored spheres are working their way through ancient Egypt, and it’s up to you to stop them before they reach the pyramids. Wielding your mystical winged-shooter, you must fire colored orbs into the chain to make matches of three or more, and eliminate the spheres from the chain. Clear out the entire chain, and you’ll work your way up to the next level.' FROM games WHERE igdb_id = 35432 ON CONFLICT (game_id, language_code) DO NOTHING;
