INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('king-arthur-fallen-champions', 10484, '2011-09-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49xu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/njm09hrf3zn3zjaodnnr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King Arthur: Fallen Champions', 'The great King Arthur has crushed his adversaries in the South but the realm of the Once and Future King still has its limit. The lands beyond the Forest of Bedegraine are wild, ruled by no one, haunted by the old gods who fought and bled here in times long past. Fallen Champions bridges the gap between King Arthur I and II with a tale of three brave souls. Sir Lionel, a brave knight from Britannia on a quest to rescue a damsel in distress. Lady Corrigan of the Sidhe, a creature of the twilight seeking the secret pathways that could lead her back to her lost home of Tir na nÓg. The third is Drest the Chosen, a shaman of the North, driven by visions of greatness and voices in the night. A knight, an enchantress, and a prophet - these three will become champions of a forgotten battle that began long, long ago.' FROM games WHERE igdb_id = 10484 ON CONFLICT (game_id, language_code) DO NOTHING;
