INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWE All Stars', 'WWE All Stars will deliver one of the greatest rosters ever assembled in a wrestling-centric videogame. Renowned WWE Legends will align with today''s most prominent Superstars, inviting players to generate fantasy matches and ultimately determine the greatest competitors of all time. In addition, each Legend and Superstar will boast a distinctive and highly stylized appearance, adding to the overall atmosphere and intrepid attitude exuding from the on-screen action.' FROM games WHERE igdb_id = 5296 ON CONFLICT (game_id, language_code) DO NOTHING;
