INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Four Swords - Anniversary Edition', 'The Legend of Zelda: Four Swords Anniversary Edition is a special commemorative version of the 2003 Game Boy Advance release, The Legend of Zelda: A Link To The Past & Four Swords. In it, you''ll embark on an exciting multiplayer adventure filled with action and puzzles as you work to save Princess Zelda from the evil Vaati. You can play with up to four friends at once, as long as each player has a copy of the game installed on their Nintendo 3DS system.' FROM games WHERE igdb_id = 45143 ON CONFLICT (game_id, language_code) DO NOTHING;
