INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7 Wonders: Magical Mystery Tour', 'See the 7 Wonders and go on a Magical Mystery Tour in this incredible Match 3 game! Go on a sensational journey to enchanting sites and match the magical runes to restore legendary locations. Repair El Dorado, Atlantis, Shangri-La, and others with help from your crew of Guild Workers. Can you gather the resources needed to repair the 7 Wonders? Take on this challenging Match 3 game and find out!' FROM games WHERE igdb_id = 4637 ON CONFLICT (game_id, language_code) DO NOTHING;
