INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer 40,000: Kill Team', 'Warhammer 40,000: Kill Team is a top down view, perspective correct, 3d arcade shooter, with twin stick control set in the Warhammer 40,000 future fantasy universe. Players play as Space Marines attempting to halt an Ork invasion spaceship, facing orks and later, Tyranids on board. Four Space Marine classes are playable including ranged specialists like the Sternguard Veteran and Techmarine, and more melee focused classes like the Vanguard Veteran and Librarian. The game supports single player and same screen multiplayer modes.
