INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Another World: 20th Anniversary Edition', 'This is an updated version of Another World (also known as Out of This World) for the 20th anniversary of the original game. It is adapted for mobile devices offering both touch controls and a virtual D-pad. The backgrounds are reworked for higher resolutions with subtler shades of light, and crisper detail and edges to the polygons and animations. It is still possible to switch to the original graphics. This version also contains remastered sound effects and three difficulty modes.' FROM games WHERE igdb_id = 16493 ON CONFLICT (game_id, language_code) DO NOTHING;
