INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Gear Solid 2: Sons of Liberty - HD Edition', 'Metal Gear Solid 2: Sons of Liberty - HD Edition feature an increased 720p resolution and a 16:9 aspect ratio, providing a clearer and wider view of the player''s surroundings compared to the original 480p resolution and 4:3 ratio of the PlayStation 2 version. Cutscenes can now be viewed in full-screen or letterboxed format, while online achievements/trophies have been added as well. Most of the additional content from Metal Gear Solid 2: Substance has also been ported in this version, such as the Missions and Snake Tales modes, although the Skateboarding mini-game that was present in the PlayStation 2 version of Substance is absent.' FROM games WHERE igdb_id = 55041 ON CONFLICT (game_id, language_code) DO NOTHING;
