INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blackwater', 'Have you got what it takes to be a Blackwater operative? The first Gesture driven Action FPS for Kinect for Xbox 360 Blackwater takes virtual combat to the next level using Kinect for Xbox 360 to create an unprecedented new level of battle immersion. Just like a real-life Blackwater operative, players must use military tactics and full body gestures to complete high-stakes assignments in some of the most dangerous places on the planet.' FROM games WHERE igdb_id = 6917 ON CONFLICT (game_id, language_code) DO NOTHING;
