INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadows of the Damned', 'From the creative genius of Suda 51 (No More Heroes) and Shinji Mikami (Resident Evil) comes an all-new psychologically twisted vision of hell unlike anything seen before. Shadows of the Damned combines visceral action with dark, grotesque horror to create a mind-shattering adventure that has to been seen to be believed.
