INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nintendogs + Cats: Toy Poodle & New Friends', 'nintendogs + cats, a game that lets players interact with realistic puppies - and kittens - in a variety of fun ways. There are three versions of the software, each with different starting breeds: French bulldog, toy poodle and golden retriever. But in each version players can unlock and enjoy more than 20 different breeds.' FROM games WHERE igdb_id = 3059 ON CONFLICT (game_id, language_code) DO NOTHING;
