INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Renegade Ops', 'In Renegade Ops you must defeat Inferno, a madman intent on global domination. Destroy enemies across a range of stunning environments using a wide variety of vehicles. Players have the choice to fight alone in single player mode, team up offline with two-player split screen or join the dynamic 4-player online co-op experience. Blast your way through enemy lines by working together, or compete for achievements as you and your friends aim to top the online leader boards.' FROM games WHERE igdb_id = 2139 ON CONFLICT (game_id, language_code) DO NOTHING;
