INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SoniComi', 'Super Sonico is a cheerful, hardworking college student and amateur musician who''s about to make her modeling debut. As her personal photographer, you will be responsible for Sonico''s image, balancing the needs of your clients with your own vision for Sonico''s future. Cute, sexy, weird -- the costumes you choose will determine her path as a model. Will you cultivate mainstream appeal? Make Sonico a subculture icon? Or will she become something even you can''t imagine? It all depends on you!' FROM games WHERE igdb_id = 33528 ON CONFLICT (game_id, language_code) DO NOTHING;
