INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Steel', 'A robot boxing game based on the film, REAL STEEL. Assume the role of a robot owner and battle against different rival robots to become the champion of robot boxing. Earn in-game cash by winning matches, and use this cash to periodically improve your robot so it can compete against stronger rivals. The vast amount of customizable parts and selectable equipment makes for over 100 million possibilities of custom robots! Stronger opponents from all around the world are waiting for you online! Build your own custom robot and aim for the top of robot boxing!' FROM games WHERE igdb_id = 47447 ON CONFLICT (game_id, language_code) DO NOTHING;
