INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Temple Run', 'Temple Run is an "endless running" video game developed by the Raleigh-based Imangi Studios. The player takes on the role of an explorer who, having stolen an idol from a temple, is chased by "demonic monkeys". The game is available on iOS and Android systems. It was released for Windows Phone 8 towards the end of March, 2013.' FROM games WHERE igdb_id = 2475 ON CONFLICT (game_id, language_code) DO NOTHING;
