INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlazBlue: Continuum Shift Extend', 'BlazBlue: Continuum Shift Extend is a 2D fighting game and the enhanced version of BlazBlue: Continuum Shift II. The game features an updated version of Calamity Trigger''s Story Mode called Blazblue Calamity Trigger Reconstruction; the inclusion of Relius Clover as a playable character; four new stories for Platinum, Makoto, Valkenhayn, and Relius; a new Unlimited Mars game mode; hidden Distortion Drives for every playable character''s Unlimited form; and further balance tweaks.' FROM games WHERE igdb_id = 6920 ON CONFLICT (game_id, language_code) DO NOTHING;
