INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cities in Motion', 'Rendered in rich detail, four of the world''s greatest cities - Vienna, Helsinki, Berlin, and Amsterdam - await the steady hand of a planner to manage their transportation needs in Cities in Motion, a city-based mass transportation simulation game. Overseeing the changing needs of people from 1920 to 2020, it''s up to you to manage everything from buses, trams and subway trains to maximize profits while pleasing commuters.' FROM games WHERE igdb_id = 1010 ON CONFLICT (game_id, language_code) DO NOTHING;
