INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Enigma: The Secret of the Sixth Ghost', 'Help the ghostly inhabitants of a haunted house as you venture into the beyond and discover the secret of the 6th ghost! Mysteriously summoned to a house you have seen only in your nightmares, you will encounter the dark and inscrutable Nathan and help the ghosts held captive there in Age of Enigma: The Secret of the Sixth Ghost. Explore this spooky Adventure game and escape from hell!' FROM games WHERE igdb_id = 22103 ON CONFLICT (game_id, language_code) DO NOTHING;
