INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rochard', 'Rochard is a game where manipulating gravity and using the G-Lifter (a gravity device used to easily move weighty objects around) are crucial elements for success. With the help of his sci-fi mining tools and taking advantage of the laws of physics, the protagonist John Rochard will carry you through a game packed with puzzles, action, humor, great music, excellent level design and a story rich of twists.' FROM games WHERE igdb_id = 5969 ON CONFLICT (game_id, language_code) DO NOTHING;
