INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkest Hour: A Hearts of Iron Game', 'Developed by a team of experienced modders from the Paradox forum, Darkest Hour is a stand-alone Hearts of Iron game. The game features a mixture of short and in-depth campaigns set across the darkest chapters of the 20th century. Play from the outbreak of the Great War up until the onset of the Cold War.' FROM games WHERE igdb_id = 2012 ON CONFLICT (game_id, language_code) DO NOTHING;
