INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NightSky', 'Nominated as a IGF Seamus McNally Finalist, NightSky is an ambient action-puzzle game that offers a gameplay experience unlike any other—cerebral challenges fill uniquely designed picturesque worlds. The player must maneuver a sphere by using realistic physics to advance; each of these worlds is broken into different areas. The original soundtrack by experimental jazz musician, Chris Schlarb will further heighten the surreal experience.' FROM games WHERE igdb_id = 15128 ON CONFLICT (game_id, language_code) DO NOTHING;
