INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocketbirds: Hardboiled Chicken', 'Annihilate an evil penguin regime in this cinematic platform adventure game offering full solo and co-op campaigns with anaglyph 3D support. Set out on a mission to assassinate the totalitarian penguin leader as Hardboiled Chicken. Destroy enemies with a slew of weapons and illuminate the secrets to his past while uncovering the real enemies of Albatropolis. Master fowl play in the co-op campaign as a pair of Budgie commandos on a mission to save the general''s daughter. Many lives will be destroyed, countless penguins will die!' FROM games WHERE igdb_id = 10767 ON CONFLICT (game_id, language_code) DO NOTHING;
