INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Adventures of Shuggy', 'The Adventures of Shuggy is a 2D platformer with a leaning towards puzzles. There are over 100 single player levels and 36 Co-Op levels connected through a gradually unlocking map screen ensuring there is always a variety of levels to choose from. Progress through the mansion is punctuated by comic book cut scenes and the occassional boss encounter. Every room in Shuggy''s castle is different, letting Shuggy travel in time, swing on ropes, turn to a zombie, shrink, grow, fly, teleport and more.' FROM games WHERE igdb_id = 11084 ON CONFLICT (game_id, language_code) DO NOTHING;
