INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Garshasp: The Monster Slayer', 'Garshasp is based on ancient Persian mythology bringing to life the epic battles of the mythological hero, Garshasp, in the ancient lands against the evil monsters. You play as Garshasp himself, the strongest man in Persian Mythology, in a journey to revenge and reclaim the legendary mace of his ancestors which is stolen by the Deevs. A journey which proves to unlock more significant hidden mysteries. The main mechanics of the game revolve around melee combat, platforming and exploration..' FROM games WHERE igdb_id = 3279 ON CONFLICT (game_id, language_code) DO NOTHING;
