INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jungle Kartz', 'Jungle Kartz is a jungle themed arcade racing game where the action takes place on a tropical island. Players can race as 8 animal characters, each with their own special abilities, and speed across 32 tracks in 3 different game modes (Quick Race, Time Trial and Tournament). Players can choose from 8 different karts and there are 9 different power-ups that can be collected and used.' FROM games WHERE igdb_id = 20825 ON CONFLICT (game_id, language_code) DO NOTHING;
