INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors 3: Xtreme Legends', 'Samurai Warriors 3: Xtreme Legends is the first standalone expansion of the 2009 title Samurai Warriors 3. The game introduces two new modes, the "Original Career" mode which allows the opportunity to create original scenarios by completing missions and acquiring gold to increase the player''s abilities and strength, as well as the series staple "Challenge" mode that has three challenges of varying objectives. It also adds new weapons, items, two new difficulty levels ("Novice" and "Hell") and stories for characters that did not have them in the original. The game also has online functionality which was not possible in the original.' FROM games WHERE igdb_id = 12286 ON CONFLICT (game_id, language_code) DO NOTHING;
