INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Feed Me Oil', 'Feed Me Oil is a physic based game where the objective is to get oil from a tube into a designated area, similar to Enigmo. To achieve this goal, the player has access to items such as walls, fans and magnets to alter the course of the oil, which would otherwise fall straight down. The game also features elements such as buttons which move walls, and paint which is needed to colour the oil before reaching the destination.' FROM games WHERE igdb_id = 93944 ON CONFLICT (game_id, language_code) DO NOTHING;
