INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Achron', 'Achron is the world''s first meta-time strategy game, allowing you to dynamically alter your past and future actions, send your units back and forth through time, even engineer temporal paradoxes that work to your advantage. Play through four single player campaigns, or then go online to face off against your friends in a fully dynamic temporal environment!' FROM games WHERE igdb_id = 16264 ON CONFLICT (game_id, language_code) DO NOTHING;
