INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nitronic Rush', 'Nitronic Rush is an experimental survival driving game developed by students at DigiPen Institute of Technology. Using the car’s many abilities (including boost, wings, and jump), avoid obstacles that the city throws at you. In many ways the game is a tribute to racing games of the 1990′s, but with fresh graphics, audio, and gameplay.' FROM games WHERE igdb_id = 51253 ON CONFLICT (game_id, language_code) DO NOTHING;
