INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alvin and the Chipmunks: Chipwrecked', 'Sing and dance as any of The Chipmunks and The Chipettes--Alvin, Simon, Theodore, Brittany, Jeanette and Eleanor. Perform more than 50 different dance moves to electrify the crowd with your on screen performance.Customize your Chipmunk before you hit the stage by choosing from a huge range of styles and accessories. Experience the movie in Story Mode with environments inspired by the film. Hear your voice “Alvin-ized” during your on-stage performance using the Kinect for Xbox 360.' FROM games WHERE igdb_id = 4670 ON CONFLICT (game_id, language_code) DO NOTHING;
