INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carnival Island', 'Carnival Island is a motion-controlled party video game. Take a trip to Carnival Island and experience the joy of classic family-friendly carnival fun in over 35 carnival games and attractions. Complete challenges, unlock adorable pets, and help bring magic and life back to the island. Using the PlayStation Move motion controller''s precise tracking technology, every toss, roll, throw, spin, and slam is translated directly into the game for extremely accurate and responsive gameplay. Whether you''re 5 or 65, family game night just got a lot more fun!' FROM games WHERE igdb_id = 20826 ON CONFLICT (game_id, language_code) DO NOTHING;
