INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloons TD 4 HD', 'This time the monkeys are serious and are ready to take down the enemy from the land, air and sea. Utilising a new ranking system you can build up your experience and gain access to even more powerful towers and upgrades. Call in mortar strikes, deploy the monkey aces and harness the power of banana farms as you bid to take down the enemy in true bloon popping fashion.' FROM games WHERE igdb_id = 88190 ON CONFLICT (game_id, language_code) DO NOTHING;
