INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Gone Sour', 'In a World Gone Sour, players take on the role of a lost Sour Patch Kid in a stylized human world, guiding their hero across some very unique environments. Use a combination of jumps, special abilities, and puzzle-solving skills to navigate the Sour Patch hero through some larger-than-life obstacles. But be careful! During this journey, players will experience some very unusual enemies- escaping from deranged humans, and facing off against mind-controlled dolls!' FROM games WHERE igdb_id = 6759 ON CONFLICT (game_id, language_code) DO NOTHING;
