INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB Bobblehead Pros', 'Step into the batter’s box with MLB Bobblehead Pros and swing for the fences! No longer do you have to show up on gameday to get your favorite player’s bobblehead doll. Now you can access all your favorite bobblehead dolls in one location! MLB Bobblehead Pros is packed with all the teams, players, and fanfare of Major League Baseball ready for you and your friends with co-op mode and online battle mode. Now you can bob your head in the big leagues!' FROM games WHERE igdb_id = 20562 ON CONFLICT (game_id, language_code) DO NOTHING;
