INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just Dance 3', 'Along with solos and duets, Just Dance 3 features quartets which allows 4 players to dance all together, as well as playlists that group songs together. Rewards can be unlocked by dancing, such as new songs, modes, as well as Dance Mashups which combine different dance routines from all three Just Dance games into one.' FROM games WHERE igdb_id = 2705 ON CONFLICT (game_id, language_code) DO NOTHING;
