INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fishing Resort', 'Fishing Resort, known in Japan and Korea as Family Fishing (ファミリーフィッシング?), is a fishing video game developed by Prope for the Wii home console. It features 8 different areas for the player to fish and do several "activities". Stores located in areas allow people to purchase items for fishing needs. Players can also take a cruiser and explore the ocean surrounding the "island" where the game takes place.' FROM games WHERE igdb_id = 19929 ON CONFLICT (game_id, language_code) DO NOTHING;
