INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Gunstringer', 'In The Gunstringer the player controls a marionette named the Gunstringer. The epic tale of the lonely gunman unfolds across several acts, each performance taking place in a hand-crafted environment. The Gunstringer has several weapons at his disposal, each tool of vengeance unleashed through the player''s gestures. The game''s lavish production features over thirty characters and countless animations.' FROM games WHERE igdb_id = 7588 ON CONFLICT (game_id, language_code) DO NOTHING;
