INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angry Birds Rio', 'Angry Birds Rio is a puzzle video game developed by Rovio Mobile. The game was released as a marketing tie-in with the 20th Century Fox animated film Rio, and was promoted along with the movie. While utilizing the same basic gameplay as the original game, Angry Birds Rio added a number of new elements, most notably the first use of boss levels. The game is consistently one of the top downloaded applications on both the App Store and the Android Market.' FROM games WHERE igdb_id = 19271 ON CONFLICT (game_id, language_code) DO NOTHING;
