INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mercury Hg', 'Mercury Hg is a puzzle platformer video game developed by British studio Eiconic Games and published by UTV Ignition Games. It is the third entry in the Mercury series. The goal is to navigate a blob of mercury to a goalpost by tilting the stage without losing all of the mercury. The mercury can be split apart into multiple blobs, change colors using Paintshops, and be remerged into a new color. In addition, the game utilizes an online leaderboard, ghost sharing, and the ability to insert music into the levels.' FROM games WHERE igdb_id = 20142 ON CONFLICT (game_id, language_code) DO NOTHING;
