INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Cat and the Coup', 'The Cat and the Coup is a documentary game in which you play the cat of Dr. Mohammed Mossadegh, the first democratically elected Prime Minister of Iran. During the summer of 1953, the CIA engineered a coup to bring about his downfall. As a player, you coax Mossadegh back through significant events of his life by knocking objects off of shelves, scattering his papers, jumping on his lap and scratching him.' FROM games WHERE igdb_id = 16241 ON CONFLICT (game_id, language_code) DO NOTHING;
