INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aselia the Eternal: The Spirit of Eternity Sword', 'With his sister Kaori held hostage, Yuuto must fight as an Etranger, a warrior of power, and take up the sword to fight alongside the beautiful female Spirits who protect the land from an evil that threatens to consume it.' FROM games WHERE igdb_id = 33476 ON CONFLICT (game_id, language_code) DO NOTHING;
