INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quake Arena Arcade', 'Quake Arena Arcade introduces the definitive, competitive first-person shooter to a new generation of gladiators. Frag up to fifteen of your friends in six game types over Xbox LIVE, including ''Deathmatch'', ''Capture the Flag'', and ''Harvester'' modes. Experience QUAKE like never before with over thirty classic maps, twelve Xbox-exclusive arenas, HD and Widescreen support, and a brand new Single Player campaign.' FROM games WHERE igdb_id = 20441 ON CONFLICT (game_id, language_code) DO NOTHING;
