INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugby Challenge', 'Developed by leading New Zealand game studio Sidhe, Rugby Challenge features 93 teams and 31 stadia including official team and competition licenses for the All Blacks, the Qantas Wallabies, the USA Eagles, Tri Nations, Bledisloe Cup, Super Rugby teams, Aviva Premiership Rugby, TOP 14 Orange, RaboDirect PRO12, ITM Cup, and Ranfurly Shield. Featuring a wealth of single player modes and online play via the Xbox LIVE online entertainment network, Rugby Challenge offers gamers an unrivalled Xbox 360 rugby experience.' FROM games WHERE igdb_id = 3009 ON CONFLICT (game_id, language_code) DO NOTHING;
