INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ratchet & Clank: All 4 One', 'We find our heroes in the midst of a dilemma of intergalactic proportions when Dr. Nefarious'' latest evil plan goes awry leaving Ratchet, Clank, Qwark and Nefarious himself caught in the snare of a powerful and mysterious machine. Begrudgingly, the Galaxy''s biggest do-gooders and its most sinister criminal must work together to discover a means of escape in this action-packed installment of the Ratchet & Clank series.' FROM games WHERE igdb_id = 1796 ON CONFLICT (game_id, language_code) DO NOTHING;
