INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Woods PGA Tour 12', 'Start your journey down the "Road to the Masters" with Tiger Woods PGA TOUR 12: The Masters. For the first time in franchise history, players will be able to experience the rich history and tradition of the Masters Tournament. Rely on the advice of your caddie to strategize and focus your game while feeling the intensity of the PGA TOUR season. Embark on the "Road to the Masters" as your career begins on the amateur tour and work your way through the Nationwide Tour, Q-School, and finally, the PGA TOUR. Tiger Woods PGA TOUR 12: The Masters has something for every golf fan and is the must-have title this year!' FROM games WHERE igdb_id = 5225 ON CONFLICT (game_id, language_code) DO NOTHING;
