INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Section 8: Prejudice', 'On the battlefield, prejudice takes many forms, knows no boundaries, and drives all conflict. In the distant future, humanity will call on its most fearless defenders to confront an emerging threat determined to eradicate all human life as we know it. Section 8: Prejudice is a sci-fi first-person shooter with dynamic combat, where every decision – from customizing equipment to activating team based objectives – drastically impacts the battlefield.' FROM games WHERE igdb_id = 19650 ON CONFLICT (game_id, language_code) DO NOTHING;
