INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samurai-warriors-chronicles', 6882, '2011-02-26', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8mzs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yvj0cqc9muic1xr3wzbg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors: Chronicles', 'Samurai Warriors: Chronicles is a hack and slash video game in the Samurai Warriors series. It was released as a launch title for the Nintendo 3DS. Samurai Warriors: Chronicles introduces several new features not included in prior Samurai Warriors games. While the top screen displays the main game, the bottom screen is used to display maps, KOs, and mission data. A player can switch between four characters during battle, switching the screen to their respective locations as well. Unlike previous titles, where the player chooses a hero and focuses on their story, in Chronicles the player chooses a male (wielding a dai-katana and rifle) or female (wielding dual swords) character which they play as a primary character in every story battle, following their own story and changing around different armies.' FROM games WHERE igdb_id = 6882 ON CONFLICT (game_id, language_code) DO NOTHING;
