INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infamous 2', 'Blamed for the destruction of Empire City and haunted by the ghosts of his past, reluctant hero Cole MacGrath makes a dramatic journey to the historic Southern city of New Marais in an effort to discover his full super-powered potential -- and face a civilization-ending confrontation with a dark and terrifying enemy from his own future. Gifted with extraordinary god-like abilities, Cole alone has the power to save humanity, but the question is-- will he choose to do so?' FROM games WHERE igdb_id = 515 ON CONFLICT (game_id, language_code) DO NOTHING;
