INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hard Corps: Uprising', 'Thrilling retro run-and-gun action is back with a vengeance in Hard Corps: Uprising, a new 2D side scroller developed by ARC System Works that pays homage to classic Konami action series. Play as the soldier Bahamut as he begins to write his legend. Battle in the grueling trenches of Arcade mode or the all-new RISING mode, where a life bar and point system allow you to purchase items and upgrades to build your soldier up and achieve ultimate victory. Need help? Partner with a friend to lay down some serious carnage.' FROM games WHERE igdb_id = 21174 ON CONFLICT (game_id, language_code) DO NOTHING;
