INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-game-of-thrones-genesis--1', 15058, '2011-08-03', 61, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20kn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nol8nlsnzk8ivetyuwkc.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Game of Thrones: Genesis', 'A Game of Thrones - Genesis" immerses you into the heart of the battles and intrigues between the Houses that shaped the Kingdom of Westeros. From Nymeria''s arrival in the Kingdom of Dorne to the awakening of the "Others" beyond the Wall, you''ll live the origins of A Game of Thrones saga through more than 1000 years of history, by taking part in Westeros'' founding events and largest battles.
