INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airline Tycoon 2', 'A decade after the best-selling Airline Tycoon comes the long awaited sequel to the legendary tongue-in-cheek economic simulation that puts players in the role of CEO of an international airline! Airline Tycoon 2 will challenge players to run a modern airline, design unique airplanes and grow a run-down carrier into a globally recognized company that passengers practically beg to fly. Airports worldwide are waiting to be explored, but beware– your rivals never rest! Crafty opponents are also working to dominate the skies… and they won’t let anything stand in the way of their goals!' FROM games WHERE igdb_id = 9958 ON CONFLICT (game_id, language_code) DO NOTHING;
